# -*- coding: utf-8 -*-
"""Part 3: legal and consumer routes (EU DSA, UK GDPR/ICO, US FTC/state AG, CA, AU)."""
from c_en2 import *
ACE = A('/appeals-centre-europe-instagram-facebook-suspension/', 'Appeals Centre Europe')
DSA = A('/dsa-appeal-right-instagram-facebook/', 'the EU DSA appeal right')
SAR = A('/uk-gdpr-subject-access-request-meta-disabled-account/', 'a subject access request')
NOTE = 'This page is general information, not legal advice.'

page('your-rights-when-meta-disables-your-account', 'legal', 'Your Rights When Instagram or Facebook Bans Your Account',
 'What the law gives you after an Instagram, Facebook or TikTok ban in the EU, UK, US, Canada and Australia, and which route fits.',
 'What are your rights when Instagram or Facebook disables your account?', 'Your rights after a ban',
 'Rights differ a lot by country. In the EU they are strongest. Here is what each one gives you, in plain words.',
 'In the EU, the Digital Services Act gives you a statement of reasons, an internal complaint at no cost and a certified out-of-court dispute body. In the UK, data protection law lets you request your personal data. In the US, there is no general appeal right, but the FTC and state attorneys general take consumer complaints.',
 [('EU', 'Statement of reasons, complaint, dispute body.'), ('UK', 'Data access and ICO complaints.'), ('US, Canada, Australia', 'Consumer and fraud complaints.')],
 [S('European Union', 'Under the Digital Services Act, platforms must explain restrictions with a statement of reasons, run an internal complaint system for at least six months after a decision, and engage with certified out-of-court dispute settlement bodies. See %s and %s.' % (DSA, ACE)),
  S('United Kingdom', 'UK GDPR gives you the right to a copy of your personal data, which can show what was recorded about the account. If the reply is late or incomplete, you can complain to the ICO. The DSA does not apply in the UK. See %s.' % SAR),
  S('United States', 'There is no federal law giving a right to appeal an account ban. The FTC collects complaints about business practices and fraud at ReportFraud.ftc.gov, and state attorneys general take consumer complaints. Neither will decide your individual account. See %s.' % A('/ftc-and-state-attorney-general-complaint-meta-account/', 'FTC and state AG complaints')),
  S('Canada and Australia', 'Canada: report fraud to the Canadian Anti-Fraud Centre, and privacy concerns to the Office of the Privacy Commissioner. Australia: ReportCyber and Scamwatch for hacks and scams, the OAIC for privacy, and the eSafety Commissioner for online abuse. %s' % NOTE),
 ],
 [('Do I have to appeal on the platform first?', 'Yes. Every route here works better, and some only work, after you have used the in-app appeal.'),
  ('Do any of these force Meta to restore my account?', 'No. Dispute body decisions are not binding, and regulators do not decide individual accounts.'),
  ('Does the DSA apply if I live in the UK or US?', 'No. It covers people located in the EU.')],
 ['People in the EU, UK, US, Canada and Australia after a ban.', 'Businesses deciding how far to take it.', 'Anyone who has run out of in-app options.'])

page('dsa-appeal-right-instagram-facebook', 'legal', 'EU DSA Appeal Right for Instagram and Facebook Bans',
 'How the EU Digital Services Act lets you challenge an Instagram, Facebook or TikTok ban: statement of reasons, complaint and dispute bodies.',
 'Live in the EU and your account was banned? The DSA gives you an appeal right.', 'EU DSA appeal right',
 'The Digital Services Act gives people in the EU three things after a ban. Here is how to use each one.',
 'If you are in the EU, the Digital Services Act requires Instagram, Facebook and TikTok to give a statement of reasons for a ban, to accept a complaint for at least six months, and to engage with certified out-of-court dispute bodies. Appeal in the app first, keep the decision, then go to a body such as Appeals Centre Europe.',
 [('Statement of reasons', 'Article 17: why and on what basis.'), ('Internal complaint', 'Article 20: at least six months.'), ('Dispute body', 'Article 21: independent review.')],
 [S('Step by step', ol(['Read the notice. It should say which rule was applied and whether the decision was automated.', 'Appeal in the app. Under Article 20 this complaint route must be open for at least six months after the decision.',
        'Save the final decision with its date.', 'Submit the dispute to a certified body, such as %s, within six months of the decision.' % ACE,
        'If the platform does not follow the rules, you can complain to your national Digital Services Coordinator, for example Coimisiún na Meán in Ireland, the ACM in the Netherlands, Arcom in France or the Bundesnetzagentur in Germany.'])),
  S('Limits', 'Dispute body decisions are not binding on the platform. Platforms must engage in good faith, but outcomes vary. %s' % NOTE),
 ],
 [('Does it cost anything?', 'The internal complaint costs nothing. Appeals Centre Europe currently charges users no fee.'),
  ('Can businesses use it?', 'Yes. Business users of the platforms are covered too.'),
  ('Does it cover Meta ad accounts?', 'The DSA focuses on content and account decisions. Ad account restrictions may not be covered by every dispute body.')],
 ['People located in an EU country.', 'Businesses and creators in the EU.', 'Anyone whose in-app appeal was rejected.'])

page('appeals-centre-europe-instagram-facebook-suspension', 'legal', 'Appeals Centre Europe: Dispute an Instagram or Facebook Ban',
 'How Appeals Centre Europe works for suspended Instagram, Facebook and TikTok accounts: who can use it, deadlines and what to expect.',
 'Can Appeals Centre Europe review your Instagram or Facebook suspension?', 'Appeals Centre Europe',
 'Appeals Centre Europe is a certified out-of-court dispute body under the EU Digital Services Act. Here is how to use it.',
 'Appeals Centre Europe reviews account suspensions and content decisions from Facebook, Instagram, Threads, TikTok, YouTube and Pinterest. You must be located in the EU, be 16 or over, and submit within six months of the platform decision. It currently charges users no fee. Its decisions are not binding, but platforms must engage.',
 [('Who', 'EU-based users aged 16 or over.'), ('When', 'Within six months of the decision.'), ('Cost', 'No user fee at present.')],
 [S('How to submit', ol(['Finish the in-app appeal and save the final decision.', 'Go to appealscentre.eu and open the dispute form.', 'Choose the platform and say it is an account suspension.',
        'Add the username, the date of the decision and the reference shown in the notice.', 'Explain briefly why the decision is wrong.'])),
  S('What to expect', 'The centre publishes its own target decision times, which are longer for complex disputes. It needs the platform to share the content, which can take time. Its own reports show it overturns some account suspension decisions, not all. Languages include English, French, German, Spanish, Italian, Polish and Dutch.'),
  S('Before you start', 'Check you are in the EU. UK, US and other users cannot use it. See %s for other countries.' % A(LEG[1], 'your rights after a ban')),
 ],
 [('Does Meta have to follow the decision?', 'No. Decisions are not binding, but platforms must engage in good faith.'),
  ('Can I use it for a hacked account?', 'It reviews platform decisions, such as a suspension. Hack recovery itself goes through the platform.'),
  ('Can Unbanz submit for me?', 'You submit it yourself. We can help you put the facts in order.')],
 ['EU users with a final suspension decision.', 'EU businesses whose account was disabled.', 'Creators in the EU who lost their account.'], area='EU')

page('statement-of-reasons-dsa-account-ban', 'legal', 'Statement of Reasons: What Meta Must Tell You (DSA)',
 'Under EU law Instagram and Facebook must explain a ban with a statement of reasons. What it should include and how to use it in an appeal.',
 'Your ban notice gave no reason? In the EU it should.', 'Statement of reasons',
 'Article 17 of the Digital Services Act sets out what a platform must tell you when it restricts your account.',
 'Under Article 17 of the EU Digital Services Act, Instagram, Facebook and TikTok must give EU users a clear statement of reasons when they restrict an account. It should say what was restricted, the facts relied on, whether automated tools were used, the rule applied, and how to appeal. Use it to write a targeted appeal.',
 [('What was restricted', 'Account, content or features.'), ('Why', 'The facts and the rule applied.'), ('How to appeal', 'The routes open to you.')],
 [S('What it should include', ul(['The type of restriction and how long it lasts.', 'The facts and circumstances relied on.', 'Whether the decision used automated means.', 'The legal or contractual ground.', 'Your redress options.'])),
  S('Using it', 'Quote the rule given and answer it directly in your appeal. If no reason was given, say so in the appeal, and mention it to a dispute body later. Platforms publish these statements, without personal data, in the EU DSA Transparency Database.'),
 ],
 [('Does this apply in the UK?', 'No. The DSA only covers people in the EU.'),
  ('What if the reason is vague?', 'Note it in your appeal and keep the screenshot for a dispute body.'),
  ('Where do I find the statement?', 'In the notice in the app and in Account status or Support Inbox.')],
 ['EU users with a vague ban notice.', 'Businesses preparing a dispute.', 'Anyone who wants to know why.'], area='EU')

page('uk-gdpr-subject-access-request-meta-disabled-account', 'legal', 'UK GDPR Subject Access Request After a Meta Ban',
 'How UK users can ask Meta for their personal data after an Instagram or Facebook ban, what to ask for, and when to complain to the ICO.',
 'In the UK and your account was disabled? You can ask Meta for your data.', 'UK subject access request',
 'A subject access request will not reverse a ban, but it can show what Meta holds about the account and the decision.',
 'Under UK GDPR you can ask Meta for a copy of the personal data it holds about you, including data linked to a disabled account. Meta must normally reply within one month, which can be extended by two months for complex requests. If the reply is late or incomplete, raise it with Meta first, then complain to the ICO.',
 [('Ask in writing', 'Through Meta’s privacy request form.'), ('One month', 'The normal deadline, extendable.'), ('ICO next', 'If the reply is late or incomplete.')],
 [S('How to make the request', ol(['Use Meta’s privacy contact form in the Privacy Center or Help Center, and choose data access.', 'Give the username, the email or phone on the account, and the date it was disabled.',
        'Ask for the personal data held about the account, including records about the enforcement decision.', 'Keep a copy and the date sent.'])),
  S('Automated decisions', 'You can also ask whether the decision was made solely by automated means. UK GDPR gives extra rights where a solely automated decision has a legal or similarly significant effect, which may apply when a business account is removed. %s' % NOTE),
  S('Complaining to the ICO', 'If Meta does not reply in time, or the reply is incomplete, write to Meta first saying so. If that does not work, complain to the Information Commissioner’s Office at ico.org.uk. The ICO looks at how your data was handled. It cannot order your account back.'),
 ],
 [('Will a subject access request get my account back?', 'No. It is about your data, not the ban decision.'),
  ('Can I use Download your information instead?', 'Only if you can still log in. A disabled account often cannot.'),
  ('Does this work in the EU?', 'Yes, EU GDPR gives the same access right. The supervisory authority differs by country.')],
 ['UK users after a ban.', 'UK businesses that lost a business account.', 'Anyone who wants their photos and messages back.'], area='GB')

page('ico-complaint-meta-account-data', 'legal', 'Complaining to the ICO About Meta and Your Account Data',
 'When a UK complaint to the ICO about Meta makes sense after a ban or hack, what the ICO can and cannot do, and how to prepare it.',
 'Thinking of complaining to the ICO about your Meta account?', 'ICO complaint',
 'The ICO deals with how organisations handle personal data. It is not an appeal body for bans.',
 'You can complain to the UK Information Commissioner’s Office if Meta did not answer a subject access request properly, mishandled your personal data, or did not respond to an objection. Raise the issue with Meta first and wait for a reply. The ICO can look at data handling, but it cannot reinstate your account.',
 [('Raise it with Meta first', 'The ICO expects that.'), ('Keep records', 'Dates and copies.'), ('Know the limits', 'It does not overturn bans.')],
 [S('When it fits', ul(['Meta did not reply to a subject access request within the deadline.', 'The reply left out data you expected.', 'You were refused access to your data without a clear reason.'])),
  S('How to prepare', ol(['Collect your request, Meta’s reply and the dates.', 'Write a short timeline.', 'Submit on ico.org.uk through the data protection complaint form.'])),
 ],
 [('How long does the ICO take?', 'It varies. The ICO publishes its current response times on its website.'),
  ('Can the ICO fine Meta for my ban?', 'The ICO deals with data protection, not content decisions.'),
  ('Is there an equivalent in Ireland?', 'Yes, the Data Protection Commission.')],
 ['UK users whose data request went unanswered.', 'Businesses with data concerns after a ban.', 'People who want a formal record.'], area='GB')

page('ftc-and-state-attorney-general-complaint-meta-account', 'legal', 'FTC or State Attorney General Complaint About Meta',
 'US options after an Instagram or Facebook ban or hack: FTC ReportFraud, state attorney general complaints, and what they actually do.',
 'In the US and thinking of reporting Meta to the FTC or your state AG?', 'FTC and state AG complaints',
 'US regulators collect complaints and look for patterns. They do not handle individual bans.',
 'In the US you can file a complaint about Meta with the FTC at ReportFraud.ftc.gov and with your state attorney general’s consumer protection office. These complaints are logged and can inform investigations, but neither agency resolves individual account decisions. Use them alongside the in-app appeal, not instead of it.',
 [('FTC', 'ReportFraud.ftc.gov.'), ('State AG', 'Consumer protection office.'), ('Alongside the appeal', 'Not a replacement.')],
 [S('When it makes sense', ul(['A paid service, such as Meta Verified or ads, was not delivered as described.', 'You were charged after losing access.', 'Fraud happened through a hacked account.'])),
  S('How to file', ol(['Write a short timeline with dates.', 'Include usernames, amounts and reference numbers.', 'File at ReportFraud.ftc.gov.', 'File with your state attorney general’s consumer complaint form.', 'For hacks with money lost, also report to IC3.gov.'])),
  S('Small businesses', 'If ads were charged after a hack, contact Meta through Billing and payments first. The Better Business Bureau also takes complaints. %s' % NOTE),
 ],
 [('Will the FTC contact Meta for me?', 'The FTC does not resolve individual complaints.'),
  ('Does my state AG help?', 'Some state offices forward complaints to the company and ask for a reply.'),
  ('Should I sue?', 'That is a decision for a lawyer. Small claims rules differ by state, and Meta’s terms include forum clauses.')],
 ['US users after a ban or hack.', 'US small businesses with ad charges.', 'Meta Verified subscribers who feel misled.'], area='US')

page('canada-australia-hacked-or-banned-account-where-to-report', 'legal', 'Hacked or Banned in Canada or Australia: Where to Report',
 'The official places to report a hacked or banned Instagram or Facebook account in Canada and Australia, and what each one handles.',
 'In Canada or Australia and your account was hacked or banned?', 'Canada and Australia routes',
 'Each country has its own services. Most help with fraud and abuse, not the ban itself.',
 'In Canada, report fraud through a hacked account to the Canadian Anti-Fraud Centre and privacy problems to the Office of the Privacy Commissioner. In Australia, use ReportCyber for hacks, Scamwatch for scams, the eSafety Commissioner for abuse, and the OAIC for privacy. Account restoration still goes through Meta’s own appeal.',
 [('Canada', 'Anti-Fraud Centre, Privacy Commissioner.'), ('Australia', 'ReportCyber, Scamwatch, eSafety, OAIC.'), ('Ban itself', 'Through Meta’s appeal.')],
 [S('Canada', ul(['Canadian Anti-Fraud Centre: fraud, scams and identity theft.', 'Office of the Privacy Commissioner of Canada: how your data was handled.', 'Local police: threats or extortion.'])),
  S('Australia', ul(['ReportCyber at cyber.gov.au: hacked accounts and cybercrime.', 'Scamwatch: scams run through your account.', 'eSafety Commissioner: cyberbullying, image-based abuse and threats.', 'OAIC: privacy complaints.'])),
 ],
 [('Will these agencies restore my account?', 'No. They handle fraud, abuse and privacy. Restoration is through the platform.'),
  ('Is there a dispute body like the EU one?', 'Not for account bans.'),
  ('What should I report first?', 'Start the platform recovery, then report fraud or threats.')],
 ['Canadian and Australian users after a hack or ban.', 'Businesses that lost money.', 'People facing threats.'], area=['CA', 'AU'])
